class Block62(nn.Module):
    '''
    Last cvv 
    '''

    def __init__(self, config):
        super().__init__()
        self.ln_1 = LayerNorm(config.n_embd, bias=config.bias)
        self.attn = CausalSelfAttention(config)
        self.ln_2 = LayerNorm(config.n_embd, bias=config.bias)
        self.mlp = MLP(config)
        nk = 5
        self.koutput = nn.Linear(config.n_embd, nk*config.n_embd,bias=False)
        self.gates = nn.Linear(config.n_embd, nk,bias=True)
        self.router = nn.Linear(config.n_embd,1,bias=False)

    def forward(self, x):
        # att = self.router(x).softmax(-1   )
        b,t,e = x.shape
        ne = e
        x2=  self.attn(self.ln_1(x))
        x3 = self.mlp(self.ln_2(x))
        # print((att*100).mean((0,1)).double())
        # self.router
        xs = torch.stack([x,x2,x3],dim=0)
        att = (self.router(self.ln_1(xs))/ne**0.5).softmax(0).squeeze(-1)
        x = torch.einsum('kbt,kbte->bte',att,xs)

        att = (self.gates(self.ln_1(x))/ne**0.5).softmax(-1)
        x = torch.einsum('btk,btke->bte',att, self.koutput(self.ln_1(x)).reshape((b,t,-1,e)))
        ## tensor([23.8678, 28.6459, 47.4863], device='cuda:0', dtype=torch.float64)

        return x



