        # yo2 = torch.einsum('btk,btke->bte',attk,vvec[idxk,:])

        eng = eng.relu()
        v,idxk = eng.topk(5,dim=-1)
        eng = eng.masked_fill(eng<v.min(-1)[0].unsqueeze(-1), 0.)

        # attk = eng.softmax(-1)
        attk = eng
        yo2 = torch.einsum('btk,ke->bte',attk,vvec)

        ### use v vector in ca

        x = (x + yinput + yo2)

