class GPT11(GPT):

    # is_add_stats = False
            
    def __init__(self, config):
        # super(GPT,self).__init__(config)
        super(GPT,self).__init__()

    # def __init__(self, config):
    #     super().__init__()
        assert config.vocab_size is not None
        assert config.block_size is not None
        self.config = config
        ne = config.n_embd
        nl = config.n_layer
        ng = config.n_head

        self.transformer = nn.ModuleDict(dict(
            wte = nn.Embedding(config.vocab_size, config.n_embd),
            wpe = nn.Embedding(config.block_size, config.n_embd),
            drop = nn.Dropout(config.dropout),
            output = nn.Linear(ne*nl,ng*ne,bias=False),
            gates = nn.Linear(ne*nl,ng,bias=True),
        # gates = md.gates(xx).softmax(-1)
        # x = torch.einsum('btk,btke->bte',gates,md.output(xx).reshape((b,t,-1,ne)))
            h = nn.ModuleList([Block11(config) for _ in range(config.n_layer)]),
            ln_f = LayerNorm(config.n_embd, bias=config.bias),
        ))
        self.lm_head = nn.Linear(config.n_embd, config.vocab_size, bias=False)
        # with weight tying when using torch.compile() some warnings get generated:
        # "UserWarning: functional_call was passed multiple values for tied weights.
        # This behavior is deprecated and will be an error in future versions"
        # not 100% sure what this is, so far seems to be harmless. TODO investigate
        self.transformer.wte.weight = self.lm_head.weight # https://paperswithcode.com/method/weight-tying

        # init all weights
        self.apply(self._init_weights)
        # apply special scaled init to the residual projections, per GPT-2 paper
        for pn, p in self.named_parameters():
            if pn.endswith('c_proj.weight'):
                torch.nn.init.normal_(p, mean=0.0, std=0.02/math.sqrt(2 * config.n_layer))

        # report number of parameters
        print("number of parameters: %.2fM" % (self.get_num_params()/1e6,))

    def forward(self, idx, targets=None):


        md = self.transformer ### model dict


        # forward the GPT model itself

        config = self.config
        nl = config.n_layer
        ne = config.n_embd
        nh = config.n_head


        device = idx.device
        b, t = idx.size()
        assert t <= self.config.block_size, f"Cannot forward sequence of length {t}, block size is only {self.config.block_size}"
        pos = torch.arange(0, t, dtype=torch.long, device=device) # shape (t)

        # forward the GPT model itself
        tok_emb = self.transformer.wte(idx) # token embeddings of shape (b, t, n_embd)
        pos_emb = self.transformer.wpe(pos) # position embeddings of shape (t, n_embd)
        x = self.transformer.drop(tok_emb + pos_emb)
        states = torch.zeros((b,t,nl,ne),device=device)
        for i,block in enumerate(self.transformer.h):
            x = block(x)
            states[:,:,i] = x
        xx = states.reshape((b,t,-1))
        gates = md.gates(xx).softmax(-1)
        x = torch.einsum('btk,btke->bte',gates,md.output(xx).reshape((b,t,-1,ne)))
        x = self.transformer.ln_f(x)

        if targets is not None:
            # if we are given some desired targets also calculate the loss
            logits = self.lm_head(x)
            loss = F.cross_entropy(logits.view(-1, logits.size(-1)), targets.view(-1), ignore_index=-1)
        else:
            # inference-time mini-optimization: only forward the lm_head on the very last position
            logits = self.lm_head(x[:, [-1], :]) # note: using list [-1] to preserve the time dim
            loss = None

        return logits, loss


import torch.nn as nn


# class CCM01(nn.Module):
class CCM01(GPT):
    '''
    compress the internal representation to discrete representations
    g200 

./
iter 1480: loss 4.1011, time 94.83ms, mfu 3.64%
iter 1490: loss 4.1817, time 94.83ms, mfu 3.65%
step 1500: train loss 4.1789, val loss 5.0421
saving checkpoint to out-shakespeare-word

step 2000: train loss 4.0252, val loss 5.0605
step 1500: train loss 4.0410, val loss 4.9773



    ### maybe overfitting?

    '''

    @classmethod
    def add_config(cls, config):
        config.mask_index = -1
        # config.optimizer ='rmsprop'
        config.optimizer ='adamw'

        config.k = 5
        config.g = 200
        # config.g = 10
        config.nrep=2
        config.use_dropout = 0
        ### lower rank for the internal embedding
        # config.n_internal = config.n_embd//16
        config.n_internal = config.n_embd//4


        # config.block_size = config.block_size+config.k
        # config.block_size = config.block_size*4
        # config.block_size = config.block_size*2
        config.method = -1
        config.n_head = 1

        config.suffix = f'{config.optimizer}-method{config.method}'
        config.is_causal=True
        # assert config.method in [5,6,7,8,9,10,11,12,13]
        assert config.optimizer
        return config


    def __init__(self, config):
        super(GPT,self).__init__(config)

        # config.block_size = config.block_size*

        config = self.add_config(config)
        assert config.vocab_size is not None
        assert config.block_size is not None
        self.config = config
        print(config)
        # breakpoint()
        ne = config.n_embd
        nh = config.n_head
        nei = config.n_internal

        self.transformer = nn.ModuleDict(dict(
            wte = nn.Embedding(config.vocab_size, config.n_embd),
            wpe = nn.Embedding(config.block_size, config.n_embd),
            # k_query = nn.Linear(config.n_embd,config.k, ),
            # k_vects = nn.Embedding(config.g, config.n_embd),
            # g_vects = nn.Embedding(config.g, config.n_embd),
            drop = nn.Dropout(config.dropout),
            lin_output   = nn.Linear(ne, nh*nei,bias=config.bias),
            lin_internal = nn.Linear(nei, ne,bias=config.bias),
            lin_internal_output = nn.Linear(nei, ne,bias=config.bias),
            lin_transit   = nn.Linear(ne,nh*nei,bias=config.bias),
            # lin_transit_2 = nn.Linear(nh*nei, ne,bias=config.bias),
            lin_input     = nn.Linear(ne,nei,bias=config.bias),
            lin_input_2   = nn.Linear(ne,ne,bias=config.bias),
            ln_f = LayerNorm(config.n_embd, bias=config.bias),
        ))
        # self.att_bias = 
        self.lm_head = nn.Linear(config.n_embd, config.vocab_size, bias=False)

        # with weight tying when using torch.compile() some warnings get generated:
        # "UserWarning: functional_call was passed multiple values for tied weights.
        # This behavior is deprecated and will be an error in future versions"
        # not 100% sure what this is, so far seems to be harmless. TODO investigate
        self.transformer.wte.weight = self.lm_head.weight # https://paperswithcode.com/method/weight-tying

        # init all weights
        self.apply(self._init_weights)
        # apply special scaled init to the residual projections, per GPT-2 paper
        for pn, p in self.named_parameters():
            if pn.endswith('c_proj.weight'):
                torch.nn.init.normal_(p, mean=0.0, std=0.02/math.sqrt(2 * config.n_layer))

        # report number of parameters
        print("number of parameters: %.2fM" % (self.get_num_params()/1e6,))


    def forward(self, idx, targets=None, gradient_only=True):
        device = idx.device
        b, t = idx.size()
        assert t <= self.config.block_size, f"Cannot forward sequence of length {t}, block size is only {self.config.block_size}"
        pos = torch.arange(0, t, dtype=torch.long, device=device) # shape (t)
        lp_internal = torch.zeros((b,),device=device)

        md = self.transformer ### model dict


        # forward the GPT model itself
        tok_emb = self.transformer.wte(idx) # token embeddings of shape (b, t, n_embd)
        pos_emb = self.transformer.wpe(pos) # position embeddings of shape (t, n_embd)

        x = tok_emb + pos_emb
        # x = tok_emb 
        if self.config.use_dropout:
            x = self.transformer.drop(x)


        lp_internal = torch.zeros((b,),device=device)
        #### the problem here is to insert context vector
        ####
        e = self.config.n_embd
        l = self.config.n_layer

        config = self.config

        ne = config.n_embd
        nh = config.n_head

        ### cpt is the post context at position 
        # cpt = torch.zeros((b,t,e),device=device) 
        cpt      = torch.zeros((b,t,e),device=device)+ x
        x_init   = x
        att_mask = torch.ones((t,t),device=device).bool()
        ### (i,j)  0 for j>i 1 for j<=i  so i is ti, j is tp
        ### need to concat a single prefix to avoid
        # att_mask = torch.tril(att_mask, diagonal=1)

        ### (tc,tp)
        att_mask = torch.tril(att_mask, diagonal=0)
        nei      = config.n_internal
        md       = self.transformer

        # ### (tp,tc)        
        # att_mask = att_mask.T

        def get_xpred(cpt):
            ### (b,tp,nh,nei)
            # xpred = cpt.matmul(wo).reshape((b,t,nh,ne))
            # xpred = md.lin_output(cpt).sigmoid().reshape((b,t,nh,ne))
            xpred = md.lin_output(cpt).reshape((b,t,nh,nei))
            return xpred


        def get_cpred(x,cpt):
            ### (b,tp,nei,nh,tc)
            ### no skip connection for the momenta
            cpred = md.lin_transit(cpt).reshape((b,t,nei,nh,1)).expand((b,t,nei,nh,t)) 
            cpred = cpred + md.lin_input(x).transpose(1,2)[:,None,:,None,:].expand((b,t,nei,nh,t)) 
            cpred = 0.5 * cpred
            # cpred = cpred.sigmoid()
            return cpred

        for i in range(4):
            xpred = get_xpred(cpt)
            cpred = get_cpred(x,cpt)

            ### (b,tp,nh,tc)
            lp = 0.
            # lp += xpred.matmul(xrep) 
            lp += torch.einsum('bphe,bce->bphc', xpred, x.matmul(md.lin_internal_output.weight)) 
            lp += torch.einsum('bpehc,bce->bphc',cpred, cpt.matmul(md.lin_internal.weight))

            ### (b,tc,nh,tp)
            lp = lp.transpose(1,3)
            
            lp = lp.masked_fill(att_mask[None,:,None,:]==0,float('-inf'))

            ### (b,tc,nh,tp)
            # att = lp.reshape.softmax((2,3))
            att = lp.reshape((b,t,-1)).softmax(-1).reshape(lp.shape)
            # 2,3))
            # breakpoint()    
            dcpt = torch.einsum('bchp,bpehc->bce', att, cpred).matmul(md.lin_internal.weight.T)
            cpt = cpt + 0.1*dcpt

        # xpred = md.lin_output(dcpt).reshape((b,t,nh,nei))
        xpred = get_xpred(cpt)
        xpred = xpred.matmul(md.lin_internal_output.weight.T).reshape((b,t,nh,ne))
        x     = xpred

        x     = self.transformer.ln_f(x)            

        logits= self.lm_head(x).log_softmax(-1).logsumexp(2)-math.log(nh)


        # if targets is not None:
        #     lp_external  = -F.cross_entropy(logits.transpose(1,2), targets, ignore_index=self.config.mask_index,reduction='none')
        #     # lp_external  = -F.cross_entropy(logits.transpose(1,2), targets, ignore_index=-1,reduction='mean')
        # else:
        #     lp_external = torch.zeros_like(logits[:,:,0])

        ### (b,t)
        if targets is not None:
            loss  = F.cross_entropy(logits.transpose(1,2), targets, ignore_index=-1,reduction='mean')
        else:
            loss  = None
        return logits, loss         

    def forward_random(self, idx, targets=None, gradient_only=True):
        device = idx.device
        b, t    = idx.size()
        ns      = 1
        idx     = idx[None].expand((ns,b,t)).reshape((ns*b,t))#.contiguous()

        if targets is not None:
            target_not_null = targets != self.config.mask_index 
            targets = targets[None].expand((ns,b,t)).reshape((ns*b,t))#.contiguous()
        else:
            target_not_null = torch.ones_like(idx)
        ct = target_not_null.sum(1)


        (logits, lp_internal, lp_external) = self._forward(idx,targets,gradient_only)

        ### (nsb,t)
        g = self.config.g
        k = self.config.k
        lp_k = k*math.log(1./t) + k*math.log(1/g)  ### adding prior on pk and gk var
        lp_total   = lp_external.sum(1)  + lp_internal

        method = self.config.method
        logits = logits.reshape(((ns,b,t,-1)))

        lp_internal = lp_internal.reshape((ns,b))
        lp_total    = lp_total.reshape((ns,b,))
        lp_external = lp_external.reshape((ns,b,t))   

        ### sampling from posterior is difficult
        ### https://www.cs.ubc.ca/~schmidtm/Courses/540-W20/L30.pdf
        
        # loss_valid = -(lp_total.sum(-1).logsumexp(0) - math.log(ns))/ct.sum(0)
        loss_valid = -(lp_total.logsumexp(0).sum(0))/ct.sum(0)

        ##(ns,b)        
        if 1:
            ### re weighted sample using q()
            ##(ns,b)
            reweight_lp  = lp_external.sum(2).log_softmax(0) 

            reweight_lp  = lp_total + reweight_lp.detach()
            # loss_grad  = -(reweight_lp.logsumexp(0).sum(0))/ct.sum(0)
            loss_grad  = -(reweight_lp.mean(0).sum(0))/ct.sum(0)
            # loss_grad = -( lp_external.sum(1) + lp_external.sum(1).detach() * lp_internal).sum(0)/ct.sum(0)# * 10

        ### (b,v)
        logits = (lp_internal[:,:,None,None] + logits.log_softmax(-1)).logsumexp(0)

        return logits, loss_grad, loss_valid



import torch.nn as nn

class Block217(nn.Module):

    def __init__(self, config):
        super().__init__()
        self.nk = nk = config.n_mix

        self.ln_1 = LayerNorm(config.n_embd, bias=config.bias)
        self.attn = CausalSelfAttention217(config)
        self.ln_2 = LayerNorm(config.n_embd, bias=config.bias)

        self.c_fc     = nn.Linear(config.n_embd, nk, bias=config.bias)
        self.c_fc2    = nn.Linear(config.n_embd, nk, bias=config.bias)
        self.c_proj2  = nn.Linear(nk, config.n_embd, bias=False)

        self.dropout = nn.Dropout(config.dropout)

        self.k_att     = nn.Linear(config.n_embd, nk, bias=True)

    def forward(self, x, x0,lpz):

        att  = self.k_att(self.ln_2(x))
        att  = att.softmax(-1)
        dist = torch.distributions.categorical.Categorical(probs=att)
        idxk = dist.sample()
        lp   = dist.log_prob(idxk)


        ctx,lpz = self.attn(self.ln_1(x),self.ln_1(x0),lpz)
        
        x = x+ctx

        # x2  = self.ln_2(x)
        # att = self.c_fc(x2).softmax(-1)
        # print(idxk[0,:10])
        # print(self.c_proj2.weight.square().sum(0))
        xo = x + self.c_proj2(self.c_fc2(x)*torch.eye(self.nk,device=x.device)[idxk]) 
        return xo, (lp + lpz)




class CausalSelfAttention217(nn.Module):

    def __init__(self, config):
        super().__init__()
        assert config.n_embd % config.n_head == 0
        # key, query, value projections for all heads, but in a batch
        self.c_attn = nn.Linear(config.n_embd, 3 * config.n_embd, bias=config.bias)
        # output projection
        self.c_proj = nn.Linear(config.n_embd, config.n_embd, bias=config.bias)
        # regularization


        self.attn_dropout = nn.Dropout(0.)
        self.resid_dropout = nn.Dropout(0.)
        
        self.n_head = config.n_head
        self.n_embd = config.n_embd
        self.dropout = config.dropout
        # flash attention make GPU go brrrrr but support is only in PyTorch >= 2.0
        self.flash = hasattr(torch.nn.functional, 'scaled_dot_product_attention')
        self.flash = False
        if not self.flash:
            print("WARNING: using slow attention. Flash Attention requires PyTorch >= 2.0")
            # causal mask to ensure that attention is only applied to the left in the input sequence
            self.register_buffer("bias", torch.tril(torch.ones(config.block_size, config.block_size))
                                        .view(1, 1, config.block_size, config.block_size))


        # self.register_buffer('idxb',torch.arange(B,device=x.device)[:,None,None])
        # self.register_buffer('idxh', torch.arange(config.n_head)[None,:,None])
            # self.idxh = torch.arange(v.size()[1],device=x.device)[None,:,None]

    def forward(self, x, x0, lpz):
        B, T, C = x.size() # batch size, sequence length, embedding dimensionality (n_embd)

        # calculate query, key, values for all heads in batch and move head forward to be the batch dim
        q, _, _  = self.c_attn(x).split(self.n_embd, dim=2)
        _, k, v  = self.c_attn(x0).split(self.n_embd, dim=2)
        k = k.view(B, T, self.n_head, C // self.n_head).transpose(1, 2) # (B, nh, T, hs)
        q = q.view(B, T, self.n_head, C // self.n_head).transpose(1, 2) # (B, nh, T, hs)
        v = v.view(B, T, self.n_head, C // self.n_head).transpose(1, 2) # (B, nh, T, hs)

        # causal self-attention; Self-attend: (B, nh, T, hs) x (B, nh, hs, T) -> (B, nh, T, T)
        if self.flash:
            assert 0,'not impl'
            # efficient attention using Flash Attention CUDA kernels
            # y = torch.nn.functional.scaled_dot_product_attention(q, k, v, attn_mask=None, dropout_p=self.dropout if self.training else 0, is_causal=True)
        else:
            # manual implementation of attention
            att = (q @ k.transpose(-2, -1)) * (1.0 / math.sqrt(k.size(-1)))
            att = att.masked_fill(self.bias[:,:,:T,:T] == 0, float('-inf'))
            att = F.softmax(att, dim=-1)

            # dist = torch.distributions.Categorical(probs=att)
            total = 10
            dist = torch.distributions.Multinomial(total,probs=att)
            ## b nh t
            idxt = dist.sample()
            ## b,t
            lp  = dist.log_prob(idxt).sum(1)
 
            # (B, nh, T, T) x (B, nh, T, hs) -> (B, nh, T, hs)
            y   = torch.eye(T,device=x.device)*idxt/total @ v

            # idxb = torch.arange(B,device=x.device)[:,None,None]
            # y = v[idxb,self.idxh,idxt,:] 
 
            # att = self.attn_dropout(att)
            # y   = att @ v # (B, nh, T, T) x (B, nh, T, hs) -> (B, nh, T, hs)

        y = y.transpose(1, 2).contiguous().view(B, T, C) # re-assemble all head outputs side by side
        # lp = 0.
        # output projection
        y = self.resid_dropout(self.c_proj(y))
        return y, (lpz + lp)



class GPT217(GPT):
    '''
    same as 215 but using a elbo to get gradient
    same as 214 but adding sampling into attention module
    same as 213 but making more layer with sampling
    same as 212 but adding baseline to stablising gradient estimation
    same as 211 but computing the per-sequence likelihood
    same as gpt 171 but using a discrete random variable at the end
    same as 141D but with a symbolic layer at the end, mixing rank-3 linear map.
    same as 141 but adding vector norm regularisation at the end
    same as 140 but using static displacement vector in MLP 
    same as 131 but using fully replaced MLP, and linear MLP activation and maps
    same as 117 but trying to use a local representation instead of a global one
    Kernellising the MLP activation function s(k) to be rank 1 bilinear kernels
    same as GPT102G but introducing a gaussian approximation of bernoulli variables
    Preprocessed token
    '''

    def __init__(self, config):
        super(GPT,self).__init__()

        config.n_mix = 4*config.n_embd

        assert config.vocab_size is not None
        assert config.block_size is not None
        self.config = config

        self.transformer = nn.ModuleDict(dict(
            wte = nn.Embedding(config.vocab_size, config.n_embd),
            wpe = nn.Embedding(config.block_size, config.n_embd),
            drop = nn.Dropout(config.dropout),
            
            # h0 = nn.ModuleList([Block140(config) for _ in range(1)]),
            h0 = nn.ModuleList([Block117(config) for _ in range(1)]),
            # h1 = nn.ModuleList([Block117(config) for _ in range(config.n_layer-1)] +  [Block130(config) for _ in range(1)]),
            h1 = nn.ModuleList([Block217(config) for _ in range(config.n_layer-2) ] +[Block217(config)]),
            hlast = Block217(config),
            ln_f = LayerNorm(config.n_embd, bias=config.bias),
        ))
        self.lm_head = nn.Linear(config.n_embd, config.vocab_size, bias=False)
        # self.lm_norm = nn.Linear(1, config.vocab_size, bias=True)
        # self.lm_null = nn.Linear(1, config.vocab_size, bias=False)
        # self.norm_m = nn.Parameter(torch.tensor(7.5))
        ### precision of the gaussian distrib
        self.norm_w = nn.Parameter(torch.tensor(0.))
        # self.norm_b = nn.Parameter(torch.tensor(0.))

        # with weight tying when using torch.compile() some warnings get generated:
        # "UserWarning: functional_call was passed multiple values for tied weights.
        # This behavior is deprecated and will be an error in future versions"
        # not 100% sure what this is, so far seems to be harmless. TODO investigate
        self.transformer.wte.weight = self.lm_head.weight # https://paperswithcode.com/method/weight-tying

        # init all weights
        self.apply(self._init_weights)
        # apply special scaled init to the residual projections, per GPT-2 paper
        for pn, p in self.named_parameters():
            if pn.endswith('c_proj.weight'):
                torch.nn.init.normal_(p, mean=0.0, std=0.02/math.sqrt(2 * config.n_layer))

        # report number of parameters
        print("number of parameters: %.2fM" % (self.get_num_params()/1e6,))
        self.reset = True

    def forward(self, idx, targets=None):
        if self.reset and not self.training:
            # print([self.norm_m.item(),self.norm_w.item(),self.norm_b.item()])
            print([self.norm_w.exp().item()])
            self.reset = False
        if self.training:
            self.reset = True
        device = idx.device
        b, t = idx.size()
        assert t <= self.config.block_size, f"Cannot forward sequence of length {t}, block size is only {self.config.block_size}"
        pos = torch.arange(0, t, dtype=torch.long, device=device) # shape (t)

        # forward the GPT model itself
        tok_emb = self.transformer.wte(idx) # token embeddings of shape (b, t, n_embd)
        pos_emb = self.transformer.wpe(pos) # position embeddings of shape (t, n_embd)

        x = tok_emb + pos_emb

        # ns = 10
        ns = 3
        x = x[None].repeat((ns,1,1,1)).reshape((-1,x.shape[1],x.shape[2]))
        x0 = x

        lpz = torch.zeros((ns*b,t,),device=x.device)

        ## pre process the token to 
        x = x0
        for block in self.transformer.h0:
            x = block(x,x0)
        x1 = x
        
        x = x1
        for block in self.transformer.h1:
            x,lpz = block(x, x1, lpz)
            # x = block(x,x1)


        block = self.transformer.hlast
        x,lpz = block(x, x0, lpz)
        x = self.transformer.ln_f(x)




        if targets is not None:

            
            ### non sequential per token loss
            # if not self.training:
            #     logits = self.lm_head(x)
            #     loss = F.cross_entropy(logits.view(-1, logits.size(-1)), targets[None].repeat((ns,1,1,1)).reshape(-1), ignore_index=-1,reduction='none')
            #     lpy = -loss.reshape((ns,b,t))
            #     # lpz = lpz.view((ns,-1))

            #     ### logmeanexp
            #     # mpy = lpy.mean(2).logsumexp(0) - math.log(ns)
            #     mpy  = lpy.logsumexp(0) - math.log(ns)
            #     loss = -mpy.mean()

            if not self.training:

                logits = self.lm_head(x)
                loss = F.cross_entropy(logits.view(-1, logits.size(-1)), targets[None].repeat((ns,1,1,1)).reshape(-1), ignore_index=-1,reduction='none')
                lpy = -loss.reshape((ns,b,t))
                lpz = lpz.view((ns,b,t))

                ### logmeanexp
                # mpy = lpy.logsumexp(0) - math.log(ns)
                
                ### per sequence estimator
                mpy  = lpy.sum(2).logsumexp(0) - math.log(ns)
                mpy  = mpy/t
                loss = -mpy.mean()

            else:
                ### estimating gradient from the p(y|z)p(z|x)
                ### lpy lpz
                logits = self.lm_head(x)
                loss = F.cross_entropy(logits.view(-1, logits.size(-1)), targets[None].repeat((ns,1,1,1)).reshape(-1), ignore_index=-1,reduction='none')
                lpy = -loss.reshape((ns,b,t))
                lpz = lpz.view((ns,b,t))

                ### estimating local log partiaion function \sum_z p(y|z) p(z|x)

                ### 1. old estimation
                # lpy  = lpy.sum(2)
                ### logmeanexp
                # cxy  = lpy.logsumexp(0) - math.log(ns)
                # loss = (lpy - cxy).exp().detach() * (lpy + lpz.sum(2)) 
                # loss = loss * ns / t

                ## 2. combined into a softmax
                lpy  = lpy.sum(2)
                # loss = lpy.softmax(0).detach()* (lpy + lpz.sum(2)) 
                lpyp = lpy.softmax(0)
                ### removing baseline from second term
                loss = lpyp.detach()* lpy + (lpyp - lpyp.mean(0,keepdims=True)).detach()* lpz.sum(2)
                loss = loss * ns/ t


                # #### 3. estimator for mean-field elbo (per sequence)
                # lpy  = lpy.sum(2)
                # loss = (lpy - lpy.mean(0,keepdims=True)).detach() * lpz.sum(2) + lpy
                # loss = loss     / t

                
                
                loss = -loss.mean()
                pass
            
        return logits,loss
            





class Block220(nn.Module):

    def __init__(self, config):
        super().__init__()
        self.ln_1 = LayerNorm(config.n_embd, bias=config.bias)
        # self.attn = CausalSelfAttention195(config)
        self.ln_2 = LayerNorm(config.n_embd, bias=config.bias)
        self.nk = nk = config.n_mix

        ## rank 5 internal
        self.ng = ng = config.n_rank
        self.ne = config.n_embd
        self.k_att     = nn.Linear(config.n_embd, nk, bias=True)
        self.norm_w = nn.Parameter(torch.tensor(0.0))
        # self.norm_w2 = nn.Parameter(torch.tensor(0.0))
        self.dropout = nn.Dropout(config.dropout)
        self.klin    = KLinear195(config)


    def forward(self, x, x0,):
        
        ### 
        ### btk
        att  = self.k_att(self.ln_2(x))
        # att  = (att*self.norm_w.exp()).softmax(-1)
        att  = (att*self.norm_w.exp()).softmax(-1)
        dist_prior = torch.distributions.categorical.Categorical(probs=att)

        ### dist_prior
        ### posterior  
        idxk = dist_prior.sample()
        
        lprior   = dist_prior.log_prob(idxk)
        ## tensor([ 4,  2,  6, 28, 21, 12,  4, 16, 11, 17], device='cuda:0')

        # ctx  = self.attn(self.ln_1(x),self.ln_1(x0), idxk)
        xo   = self.klin(self.ln_1(x0), idxk)

        return xo,lprior



