        xz_noise = self.transformer.comp_out(xz_noise)
        # xz_noise[:,:, self.nm_a:] = 0.

        if _disabled:
            ## [IMP] test whether memory slot is passing information
            # tok_emb = torch.cat([torch.zeros_like(xz_noise), tok_emb],dim=1)
            tok_emb = torch.cat([torch.zeros_like(xz_noise) + xz_noise.mean((0,1),keepdims=True), tok_emb],dim=1)
        else:
            tok_emb = torch.cat([xz_noise, tok_emb],dim=1)
        # lprior = 

        x = tok_emb + pos_emb
        for block in self.transformer.h0:
            x = block(x,x)

        x = x[:,nm:]

        x = self.transformer.ln_f(x)



        if targets is not None:

            logits = self.lm_head(x)
            loss = F.cross_entropy(logits.view(-1, logits.size(-1)), targets[None].repeat((ns,1,1,1)).reshape(-1), ignore_index=-1,reduction='none')
            lpy = -loss.reshape((ns,b,t)).sum(-1)

            lpz = lpz.reshape(ns,b,-1).sum(-1)
            lpe = lpe.reshape(ns,b,-1).sum(-1)
            
            # lpe
            # lpq = lpq.reshape(ns,b,-1).sum(-1)

            if not self.training:

                # print(lpy.mean().item(),lpz.mean().item(),lpq.mean().item())
                # loss = lpy + lpz - lpq
                # loss = lpy
                loss = lpy + lpz
                # lpz = lpz.view((ns,b,t))

                ### logmeanexp
                # mpy = lpy.logsumexp(0) - math.log(ns)                

                loss = -loss.mean() / t

            else:
                ### estimating gradient from the p(y|z)p(z|x)
                ### lpy lpz
                # logits = self.lm_head(x)
                # loss = F.cross_entropy(logits.view(-1, logits.size(-1)), targets[None].repeat((ns,1,1,1)).reshape(-1), ignore_index=-1,reduction='none')
                # lpy = -loss.reshape((ns,b,t))
                # lpz = lpz.view((ns,b,t))

                ### estimating local log partiaion function \sum_z p(y|z) p(z|x)

                ### 1. old estimation
                # lpy  = lpy.sum(2)
                ### logmeanexp
                # cxy  = lpy.logsumexp(0) - math.log(ns)
                # loss = (lpy - cxy).exp().detach() * (lpy + lpz.sum(2)) 
                # loss = loss * ns / t

                # loss = lpy
                loss = lpy + lpz + lpe
                loss = -loss.mean() / t


                # elbo = lpy + lpz - lpq
                # loss = elbo + (elbo-elbo.mean(0,keepdims=True)).detach()*lpq                
                # loss = -loss.mean() / t


                # ### 2. combined into a softmax
                # lpy  = lpy.sum(2)
                # # loss = lpy.softmax(0).detach()* (lpy + lpz.sum(2)) 
                # lpyp = lpy.softmax(0)
                # ### removing baseline from second term
                # # loss = lpyp.detach()* lpy + (lpyp - lpyp.mean(0,keepdims=True)).detach()* lpz.sum(2)
