        out = out.log_softmax(-1)

        lpz = torch.einsum('btec,btec->bt', torch.eye(self.nsep,device=xz_noise.device)[xz_int.long(),:], out)
        # print(out.exp()[0,5,:3,:10]*self.nsep)
        return lpz



